/**
 * Create a ledger (chart-of-accounts account) without leaving the current form.
 * The account number is generated by the API; normal balance follows the chosen group.
 */
import { useEffect, useState } from "react";
import { X } from "lucide-react";
import { api, type AccountGroupResponse, type ChartOfAccountResponse } from "@/api/client";
import { Button } from "@/components/ui/button";
import { logApiError } from "@/utils/logApiError";

const CTL = "w-full rounded-lg border border-border-strong bg-surface-raised px-3 py-2 text-sm";

function normalBalanceFor(group: AccountGroupResponse): "debit" | "credit" {
  if (group.default_normal_balance) return group.default_normal_balance;
  return group.nature === "Asset" || group.nature === "Expense" ? "debit" : "credit";
}

export function LedgerQuickCreateModal({
  open,
  initialName,
  onClose,
  onCreated,
}: {
  open: boolean;
  initialName?: string;
  onClose: () => void;
  onCreated: (account: ChartOfAccountResponse) => void;
}) {
  const [groups, setGroups] = useState<AccountGroupResponse[]>([]);
  const [name, setName] = useState("");
  const [groupId, setGroupId] = useState<number | "">("");
  const [openingBalance, setOpeningBalance] = useState("0");
  const [billWise, setBillWise] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!open) return;
    setName(initialName ?? "");
    setOpeningBalance("0");
    setBillWise(false);
    setError("");
    let cancelled = false;
    void api
      .listAccountGroups()
      .then((rows) => {
        if (cancelled) return;
        const postable = rows.filter((g) => g.is_active !== false && g.allow_posting !== false && !g.is_summary_group);
        setGroups(postable);
      })
      .catch((e) => {
        logApiError("LedgerQuickCreateModal.listAccountGroups", e);
        if (!cancelled) setError("Could not load account groups.");
      });
    return () => {
      cancelled = true;
    };
  }, [open, initialName]);

  if (!open) return null;

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    e.stopPropagation();
    const group = groups.find((g) => g.id === groupId);
    if (!name.trim()) return setError("Enter a ledger name.");
    if (!group) return setError("Choose an account group.");
    setBusy(true);
    setError("");
    try {
      const created = await api.createChartOfAccount({
        name: name.trim(),
        group_id: group.id,
        normal_balance: normalBalanceFor(group),
        opening_balance: openingBalance || "0",
        enable_bill_wise: billWise,
        is_active: true,
      });
      onCreated(created);
      onClose();
    } catch (err) {
      logApiError("LedgerQuickCreateModal.create", err);
      setError(err instanceof Error ? err.message : "Could not create ledger.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-labelledby="ledger-quick-create-title"
    >
      <form
        className="w-full max-w-md space-y-3 rounded-xl border border-border bg-surface-raised p-5 shadow-xl"
        onClick={(e) => e.stopPropagation()}
        onSubmit={handleSubmit}
        onKeyDown={(e) => {
          if (e.key === "Escape") onClose();
        }}
      >
        <div className="flex items-center justify-between">
          <h2 id="ledger-quick-create-title" className="text-base font-semibold text-text-primary">
            New ledger
          </h2>
          <button type="button" onClick={onClose} aria-label="Close" className="rounded-md p-1 text-text-muted hover:bg-surface-subtle">
            <X className="h-4 w-4" />
          </button>
        </div>
        {error ? (
          <div className="rounded-md border border-status-danger/30 bg-status-danger-subtle px-3 py-2 text-sm text-status-danger-foreground">{error}</div>
        ) : null}
        <div>
          <label className="mb-1 block text-xs font-medium text-text-secondary">Ledger name</label>
          <input className={CTL} value={name} onChange={(e) => setName(e.target.value)} autoFocus required />
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-text-secondary">Account group (under)</label>
          <select className={CTL} value={groupId} onChange={(e) => setGroupId(e.target.value ? Number(e.target.value) : "")} required>
            <option value="">Select group…</option>
            {groups.map((g) => (
              <option key={g.id} value={g.id}>
                {g.code} - {g.name} ({g.nature})
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-text-secondary">Opening balance</label>
          <input className={CTL} type="number" step="0.01" value={openingBalance} onChange={(e) => setOpeningBalance(e.target.value)} />
        </div>
        <label className="flex items-center gap-2 text-sm text-text-secondary">
          <input type="checkbox" checked={billWise} onChange={(e) => setBillWise(e.target.checked)} />
          Track bill-wise (for customer / supplier ledgers)
        </label>
        <div className="flex justify-end gap-2 pt-1">
          <Button type="button" variant="outline" onClick={onClose} disabled={busy}>
            Cancel
          </Button>
          <Button type="submit" disabled={busy}>
            {busy ? "Saving…" : "Create ledger"}
          </Button>
        </div>
      </form>
    </div>
  );
}
